param([string[]]$Modes, [string]$OutDir = 'C:\b\wk7\h', [int]$TimeoutSec = 1200,
      [string]$Exe = 'C:\src\JusPrin\build\tests\shell\Release\shell_integration_harness.exe',
      [string]$WebView = 'C:\b\wk7\webview')
# Runs shell-harness modes one after another. Each mode gets its own log and a
# time limit; a run that stalls is killed and reported as a stall, not a pass.
# A mode is a quoted argument string, e.g. "--check-print" or "--print-history C:\b\wk7\cap\ph".
Add-Type -AssemblyName System.Windows.Forms
New-Item -ItemType Directory -Force $OutDir | Out-Null
$env:WEBVIEW2_USER_DATA_FOLDER = $WebView
$env:PATH = "C:\Users\guitest\.local\node-v24.21.0-win-x64;$env:PATH"
foreach ($mode in $Modes) {
    # A pointer resting over the window hovers menu rows and steals keyboard selection.
    [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point(5000, 5000)
    $argList = if ($mode -eq 'default') { @() } else { $mode -split ' ' }
    $name = if ($mode -eq 'default') { 'default' } else { ($argList[0] -replace '^--', '') }
    $err = Join-Path $OutDir "$name.err"; $out = Join-Path $OutDir "$name.out"
    $started = Get-Date
    $p = if ($argList.Count) {
        Start-Process -FilePath $Exe -ArgumentList $argList -PassThru -NoNewWindow -RedirectStandardError $err -RedirectStandardOutput $out
    } else {
        Start-Process -FilePath $Exe -PassThru -NoNewWindow -RedirectStandardError $err -RedirectStandardOutput $out
    }
    $handle = $p.Handle  # keeps ExitCode readable after exit
    $finished = $p.WaitForExit($TimeoutSec * 1000)
    if (-not $finished) { Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue; $p.WaitForExit(10000) | Out-Null }
    $seconds = [int]((Get-Date) - $started).TotalSeconds
    $checks = Select-String -Path $err -Pattern '^HARNESS CHECK (\S+) (PASS|FAIL)' -ErrorAction SilentlyContinue
    $pass = @($checks | Where-Object { $_.Matches[0].Groups[2].Value -eq 'PASS' }).Count
    $fail = @($checks | Where-Object { $_.Matches[0].Groups[2].Value -eq 'FAIL' })
    $result = (Select-String -Path $err -Pattern '^HARNESS RESULT' -ErrorAction SilentlyContinue | Select-Object -Last 1).Line
    $status = if (-not $finished) { 'STALLED' } elseif (-not $result) { "NO-RESULT exit=$($p.ExitCode)" } else { "$result exit=$($p.ExitCode)" }
    "[$name] ${seconds}s pass=$pass fail=$($fail.Count) :: $status"
    foreach ($f in $fail) { "    FAIL $($f.Matches[0].Groups[1].Value)" }
}

