// Starts each page's Vite dev server and asks it for files the CSS really uses,
// and for one it must keep refusing.
import { spawn, execSync } from 'node:child_process';
const root = 'C:/src/JusPrin';
for (const page of ['AgentUI', 'HomeUI']) {
  const dir = `${root}/src/slic3r/GUI/JusPrin/${page}`;
  const child = spawn('npm.cmd', ['run', 'dev'], { cwd: dir, shell: true });
  let port;
  const ready = new Promise((resolve) => {
    const read = (d) => {
      const m = String(d).replace(/\x1b\[[0-9;]*m/g, '').match(/localhost:(\d+)/);
      if (m) { port = m[1]; resolve(); }
    };
    child.stdout.on('data', read);
    child.stderr.on('data', read);
  });
  await Promise.race([ready, new Promise((r) => setTimeout(r, 30000))]);
  console.log(`== ${page} dev server on port ${port}`);
  const base = `http://127.0.0.1:${port}`;
  const css = await (await fetch(`${base}/src/styles.css?direct`)).text();
  const urls = [...new Set([...css.matchAll(/url\(["']?([^"')]+)["']?\)/g)].map((m) => m[1]))].filter((u) => !u.startsWith('data:'));
  const pick = [urls.find((u) => u.endsWith('.woff')), urls.find((u) => u.endsWith('.svg'))].filter(Boolean);
  console.log(`css references ${urls.length} files; sample ${pick.join(', ')}`);
  let ok = 0, bad = [];
  for (const u of urls) {
    const r = await fetch(new URL(u, base));
    if (r.status === 200 && Number(r.headers.get('content-length') ?? 1) > 0) ok++;
    else bad.push(`${r.status} ${u}`);
  }
  console.log(`served ${ok}/${urls.length}`, bad.slice(0, 5));
  for (const u of [`/@fs/${root}/AGENTS.md`, `/@fs/${root}/resources/profiles/BBL.json`]) {
    const r = await fetch(`${base}${u}`);
    console.log(`outside the allow list ${u}: ${r.status}`);
  }
  execSync(`taskkill /pid ${child.pid} /T /F`, { stdio: 'ignore' });
}
process.exit(0);

