"""For every chat in a --request-log folder: is each request's input exactly the
previous request's input plus new items? Requests of a chat are grouped by
prompt_cache_key; requests without one (titles) are skipped."""
import json, pathlib, sys, collections

log = pathlib.Path(sys.argv[1])
chats = collections.defaultdict(list)
for f in sorted(log.glob("*-request.json")):
    body = json.loads(f.read_bytes())
    key = body.get("prompt_cache_key")
    if key:
        chats[key].append((f.name, body))

pairs = bad = crlf = 0
first_bad = []
for key, requests in chats.items():
    for (a_name, a), (b_name, b) in zip(requests, requests[1:]):
        pairs += 1
        ai, bi = a.get("input", []), b.get("input", [])
        same_head = a.get("instructions") == b.get("instructions") and a.get("tools") == b.get("tools")
        if bi[: len(ai)] != ai or not same_head:
            bad += 1
            if len(first_bad) < 8:
                at = next((i for i, (x, y) in enumerate(zip(ai, bi)) if x != y), min(len(ai), len(bi)))
                first_bad.append((key[-12:], a_name, b_name, at, len(ai), len(bi), same_head))
for _, requests in chats.items():
    for name, body in requests:
        if "\\r\\n" in json.dumps(body.get("input", [])):
            crlf += 1
            break
print(f"chats={len(chats)} pairs={pairs} not-pure-append={bad} chats-with-crlf-in-input={crlf}")
for row in first_bad:
    print("  ", row)

