// A local stand-in for the OpenAI Responses API, so the Agent chat runs for real
// with nothing sent to any provider. Every request body is kept for the append check.
import http from 'node:http';
import { writeFileSync, mkdirSync } from 'node:fs';

const logDir = 'C:/b/wk7/mock-log';
mkdirSync(logDir, { recursive: true });
let count = 0;
const long = Array.from({ length: 14 }, (_, i) =>
  `**Step ${i + 1}.** This is a deliberately long paragraph of a plan, so the thread has to scroll on a window of any size. ` +
  `It talks about walls, infill, cooling and first layer adhesion for a while, then ends. `).join('\n\n');

function lastUserText(body) {
  const input = body.input ?? [];
  for (let i = input.length - 1; i >= 0; i--) {
    if (input[i].role !== 'user') continue;
    const c = input[i].content;
    if (typeof c === 'string') return c;
    if (Array.isArray(c)) return c.map((p) => p.text ?? '').join(' ');
  }
  return '';
}
const hasCallResult = (body) => (body.input ?? []).at(-1)?.type === 'function_call_output';

http.createServer((req, res) => {
  let raw = '';
  req.on('data', (d) => (raw += d));
  req.on('end', async () => {
    const n = String(++count).padStart(4, '0');
    writeFileSync(`${logDir}/${n}-request.json`, raw);
    const body = JSON.parse(raw);
    res.writeHead(200, { 'Content-Type': 'text/event-stream' });
    const send = (e) => res.write(`data: ${JSON.stringify(e)}\n\n`);
    const finish = (output) => {
      send({ type: 'response.completed', response: { output, usage: { input_tokens: 10, output_tokens: 10, total_tokens: 20 } } });
      res.end();
    };
    const text = lastUserText(body);
    if (!body.tools) { // a title request
      send({ type: 'response.output_text.delta', delta: 'Test chat' });
      return finish([{ type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'Test chat' }] }]);
    }
    if (/failing action/.test(text) && !hasCallResult(body)) {
      return finish([{ type: 'function_call', call_id: `call_${n}`, name: 'settings_get',
        arguments: JSON.stringify({ keys: ['layer_height'], scope: 'filament', target: { preset: 'No Such Preset' } }) }]);
    }
    const reply = hasCallResult(body) ? 'That read failed, so I answered around it.' : /short/.test(text) ? 'A short answer.' : long;
    for (let i = 0; i < reply.length; i += 40) {
      send({ type: 'response.output_text.delta', delta: reply.slice(i, i + 40) });
      await new Promise((r) => setTimeout(r, 30));
    }
    finish([{ type: 'message', role: 'assistant', content: [{ type: 'output_text', text: reply }] }]);
  });
}).listen(8765, '127.0.0.1', () => console.log('mock listening'));

// Drives the real Agent page over DevTools: real typed input and real wheel events.
const targets = await (await fetch('http://127.0.0.1:9333/json/list')).json();
const page = targets.find((t) => t.type === 'page' && t.url.includes('agent/index.html') && !t.url.includes('panel='));
const socket = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => socket.addEventListener('open', r));
let next = 0;
const call = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++next;
  const on = (e) => { const m = JSON.parse(e.data); if (m.id !== id) return; socket.removeEventListener('message', on);
    m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); };
  socket.addEventListener('message', on);
  socket.send(JSON.stringify({ id, method, params }));
});
const ev = async (expression) => (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const state = () => ev(`(() => {
  const all = [...document.querySelectorAll('*')].filter((e) => e.scrollHeight > e.clientHeight + 4 && getComputedStyle(e).overflowY.match(/auto|scroll/) && e.querySelector('.message-list-content'));
  const s = document.querySelector('.message-list-content')?.parentElement;
  const el = all[0] ?? s;
  return { top: Math.round(el.scrollTop), gapToBottom: Math.round(el.scrollHeight - el.clientHeight - el.scrollTop), height: el.scrollHeight, jump: !!document.querySelector('.jump-to-latest'), generating: !!document.querySelector('[aria-label*="Stop" i]') };
})()`);
const type = async (text) => {
  await ev("document.querySelector('textarea').focus()");
  await call('Input.insertText', { text });
  for (const t of ['keyDown', 'keyUp'])
    await call('Input.dispatchKeyEvent', { type: t, key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: t === 'keyDown' ? '\r' : undefined });
};
const wheel = async (deltaY) => {
  const box = await ev(`(() => { const r = document.querySelector('.message-list-content').getBoundingClientRect(); return { x: r.x + r.width/2, y: Math.max(r.y, 200) + 60 }; })()`);
  await call('Input.dispatchMouseEvent', { type: 'mouseWheel', x: box.x, y: box.y, deltaX: 0, deltaY });
};
const settle = async () => { for (let i = 0; i < 80; i++) { await sleep(500); const a = await state(); await sleep(400); const b = await state(); if (a.height === b.height && !b.generating) return b; } return state(); };
const log = (label, s) => console.log(label.padEnd(58), JSON.stringify(s));

await call('Runtime.enable');
await type('Plan this print for me');
await sleep(1500);
log('1. while the first long answer streams', await state());
log('1. after it finishes (following: gap should be ~0)', await settle());

await wheel(-1200); await sleep(800);
const held = await state();
log('2. wheel up: view holds and Jump appears', held);
await sleep(1500);
log('2. still held 1.5 s later', await state());

await type('Another plan please, I scrolled up');
await sleep(700);
log('3. person sends: scrolls to bottom, Jump gone', await state());
log('3. the answer finished, still following', await settle());

await type('Another long one');
await sleep(1200);
await wheel(-1500); await sleep(600);
const during = await state();
log('4. wheel up during streaming', during);
await sleep(2500);
const later = await state();
log('4. new text keeps coming, the view must not move', later);
log('4. answer finished, view still held', await settle());

await ev("document.querySelector('.jump-to-latest')?.click()");
await sleep(1200);
log('5. Jump to latest clicked: at bottom, button gone', await state());

await type('short question using the failing action');
const done = await settle();
log('6. a turn with a failed action', done);
const line = await ev(`[...document.querySelectorAll('button,summary')].map((b) => b.innerText.trim()).filter((t) => /action/.test(t)).slice(-1)[0]`);
console.log('   activity line:', line);
await ev(`(() => { const b = [...document.querySelectorAll('button,summary')].filter((x) => /action/.test(x.innerText)).pop(); b.click(); })()`);
await sleep(600);
const row = await ev(`[...document.querySelectorAll('button,summary')].map((b) => b.innerText.trim()).filter((t) => /settings_get|Failed/.test(t)).slice(-1)[0]`);
console.log('   opened log row:', row);
await ev(`(() => { const b = [...document.querySelectorAll('button,summary')].filter((x) => /settings_get|Failed/.test(x.innerText)).pop(); b.click(); })()`);
await sleep(600);
const shot = await call('Page.captureScreenshot', { format: 'png' });
(await import('node:fs')).writeFileSync('C:/b/wk7/c1-actionlog.png', Buffer.from(shot.data, 'base64'));
console.log('   copy button present:', await ev(`[...document.querySelectorAll('button')].some((b) => /Copy details/.test(b.innerText))`));
socket.close();
process.exit(0);

