// A local stand-in for Anthropic's Messages API, for a dry run of the live tests.
import http from 'node:http';
http.createServer((req, res) => {
  let raw = '';
  req.on('data', (d) => (raw += d));
  req.on('end', () => {
    const body = JSON.parse(raw || '{}');
    res.writeHead(200, { 'Content-Type': 'text/event-stream' });
    const send = (type, e) => res.write(`event: ${type}\ndata: ${JSON.stringify({ type, ...e })}\n\n`);
    const last = (body.messages ?? []).filter((m) => m.role === 'user').at(-1);
    const answered = Array.isArray(last?.content) && last.content.some((b) => b.type === 'tool_result');
    send('message_start', { message: { id: 'msg_1', role: 'assistant', content: [], usage: { input_tokens: 10, output_tokens: 1 } } });
    if (body.tools && !answered) {
      send('content_block_start', { index: 0, content_block: { type: 'tool_use', id: 'toolu_1', name: 'workspace_inspect', input: {} } });
      send('content_block_delta', { index: 0, delta: { type: 'input_json_delta', partial_json: '{"sections":["summary"]}' } });
      send('content_block_stop', { index: 0 });
      send('message_delta', { delta: { stop_reason: 'tool_use' }, usage: { output_tokens: 5 } });
    } else {
      send('content_block_start', { index: 0, content_block: { type: 'text', text: '' } });
      send('content_block_delta', { index: 0, delta: { type: 'text_delta', text: body.tools ? 'checked' : 'Backpack frame' } });
      send('content_block_stop', { index: 0 });
      send('message_delta', { delta: { stop_reason: 'end_turn' }, usage: { output_tokens: 5 } });
    }
    send('message_stop', {});
    res.end();
  });
}).listen(8766, '127.0.0.1', () => console.log('anthropic stand-in listening'));

