$red = [System.Drawing.Color]::FromArgb(214, 40, 40); $green = [System.Drawing.Color]::FromArgb(30, 130, 76)
$ink = [System.Drawing.Color]::FromArgb(25, 25, 30); $grey = [System.Drawing.Color]::FromArgb(80, 80, 90)
$titleFont = New-Object System.Drawing.Font 'Segoe UI Semibold', 30
$bodyFont  = New-Object System.Drawing.Font 'Segoe UI', 21
$tagFont   = New-Object System.Drawing.Font 'Segoe UI Semibold', 21
$noteFont  = New-Object System.Drawing.Font 'Segoe UI Semibold', 19

# $panels: @{ File; Crop=@(x,y,w,h) or $null; Scale; Tag; Ok=$true/$false; Note; Marks=@(@(x,y,w,h),...) in source pixels }
function Compose($name, $title, $body, $panels, [int]$width = 1800) {
    $probe = [System.Drawing.Graphics]::FromImage((New-Object System.Drawing.Bitmap 1, 1))
    $inner = $width - 80
    $titleH = [int]$probe.MeasureString($title, $titleFont, $inner).Height + 8
    $bodyH  = [int]$probe.MeasureString($body, $bodyFont, $inner).Height + 8
    $y = 30 + $titleH + $bodyH + 24
    $laid = @()
    foreach ($p in $panels) {
        $img = [System.Drawing.Bitmap]::FromFile($p.File)
        $c = if ($p.Crop) { $p.Crop } else { @(0, 0, $img.Width, $img.Height) }
        $w = [int]($c[2] * $p.Scale); $h = [int]($c[3] * $p.Scale)
        $noteH = if ($p.Note) { [int]$probe.MeasureString($p.Note, $noteFont, $inner).Height + 6 } else { 0 }
        $laid += @{ Img = $img; C = $c; W = $w; H = $h; P = $p; Y = $y; NoteH = $noteH }
        $y += 44 + $noteH + $h + 30
    }
    $bmp = New-Object System.Drawing.Bitmap $width, $y
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.Clear([System.Drawing.Color]::White); $g.SmoothingMode = 'AntiAlias'; $g.InterpolationMode = 'HighQualityBicubic'; $g.TextRenderingHint = 'AntiAliasGridFit'
    $brush = { param($col) New-Object System.Drawing.SolidBrush $col }
    $g.DrawString($title, $titleFont, (& $brush $ink), (New-Object System.Drawing.RectangleF 40, 26, $inner, $titleH))
    $g.DrawString($body, $bodyFont, (& $brush $grey), (New-Object System.Drawing.RectangleF 40, (26 + $titleH), $inner, $bodyH))
    foreach ($l in $laid) {
        $p = $l.P; $col = if ($p.Ok) { $green } else { $red }
        $tagW = [int]$g.MeasureString($p.Tag, $tagFont).Width + 24
        $g.FillRectangle((& $brush $col), 40, $l.Y, $tagW, 38)
        $g.DrawString($p.Tag, $tagFont, [System.Drawing.Brushes]::White, 50, ($l.Y + 1))
        $top = $l.Y + 44
        if ($p.Note) { $g.DrawString($p.Note, $noteFont, (& $brush $col), (New-Object System.Drawing.RectangleF 40, $top, $inner, $l.NoteH)); $top += $l.NoteH }
        $dest = New-Object System.Drawing.Rectangle 40, $top, $l.W, $l.H
        if ($p.Pixelated) { $g.InterpolationMode = 'NearestNeighbor'; $g.PixelOffsetMode = 'Half' }
        $g.DrawImage($l.Img, $dest, (New-Object System.Drawing.Rectangle $l.C[0], $l.C[1], $l.C[2], $l.C[3]), 'Pixel')
        $g.InterpolationMode = 'HighQualityBicubic'; $g.PixelOffsetMode = 'Default'
        $g.DrawRectangle((New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(200, 200, 205)), 1), $dest)
        $pen = New-Object System.Drawing.Pen $col, 5
        foreach ($m in $p.Marks) {
            $g.DrawRectangle($pen, [int](40 + ($m[0] - $l.C[0]) * $p.Scale), [int]($top + ($m[1] - $l.C[1]) * $p.Scale), [int]($m[2] * $p.Scale), [int]($m[3] * $p.Scale))
        }
    }
    $bmp.Save("$dst\$name.png"); $g.Dispose(); $bmp.Dispose()
    foreach ($l in $laid) { $l.Img.Dispose() }
    "$dst\$name.png  height $y"
}

