45	{
46	public:
47	    Input(IssueOverlay& overlay, wxWindow& window) : m_overlay(overlay)
48	    {
49	        window.Bind(wxEVT_CHAR, &Input::on_char, this);
50	        window.Bind(wxEVT_LEFT_DOWN, &Input::on_press, this);
51	        window.Bind(wxEVT_MIDDLE_DOWN, &Input::on_press, this);
