290	bool IssueOverlay::selection_holds(const PrintIssue& issue) const
291	{
292	    const Model* model = m_canvas.get_model();
293	    if (model == nullptr)
294	        return false;
295	    for (const auto& [object_index, instances] : m_canvas.get_selection().get_content()) {
296	        // The wipe tower is selected under an index that is no object's.
297	        if (object_index < 0 || object_index >= int(model->objects.size()))
298	            continue;
299	        const ModelObject* object = model->objects[object_index];
300	        if (object->id().id != issue.object)
301	            continue;
302	        if (issue.instance == 0)
303	            return true;
304	        for (const int instance_index : instances)
305	            if (instance_index >= 0 && instance_index < int(object->instances.size()) &&
306	                object->instances[instance_index]->id().id == issue.instance)
307	                return true;
308	    }
309	    return false;
310	}
