313	{
314	    if (snapshot.session == m_known_session && snapshot.generation == m_known_generation)
315	        return;
316	    // Another project's issues are all new, whatever their ids.
317	    if (snapshot.session != m_known_session)
318	        m_known.clear();
319	    m_known_session    = snapshot.session;
320	    m_known_generation = snapshot.generation;
321	    std::set<std::string> ids;
322	    bool arrived = false;
323	    for (const PrintIssue& issue : snapshot.issues) {
324	        arrived = arrived || m_known.count(issue.id) == 0;
325	        ids.insert(issue.id);
326	    }
327	    m_known = std::move(ids);
328	    if (arrived) {
329	        m_announced = std::chrono::steady_clock::now();
330	        ++m_announcements;
331	    }
332	}
