355	std::optional<IssueOverlay::Target> IssueOverlay::target_of(const PrintIssue& issue) const
356	{
357	    const Model* model = m_canvas.get_model();
358	    if (model == nullptr || issue.object == 0)
359	        return std::nullopt;
360	    // The object's box in the scene as it is drawn now, so a drag that has
361	    // not been committed to the model still carries the bubble.
362	    BoundingBoxf3 box;
363	    for (const GLVolume* volume : m_canvas.get_volumes().volumes) {
364	        const int object_index = volume->object_idx(), instance_index = volume->instance_idx();
365	        if (object_index < 0 || object_index >= int(model->objects.size()))
366	            continue;
367	        const ModelObject* object = model->objects[object_index];
368	        if (object->id().id != issue.object || instance_index < 0 || instance_index >= int(object->instances.size()))
369	            continue;
370	        if (issue.instance != 0 && object->instances[instance_index]->id().id != issue.instance)
371	            continue;
372	        box.merge(volume->transformed_bounding_box());
373	    }
374	    if (!box.defined)
375	        return std::nullopt;
376	
377	    const Camera& camera = wxGetApp().plater()->get_camera();
378	    const Eigen::Matrix4d to_clip = camera.get_projection_matrix().matrix() * camera.get_view_matrix().matrix();
379	    const std::array<int, 4>& viewport = camera.get_viewport();
380	    const auto project = [&](double x, double y, double z) -> std::optional<ImVec2> {
381	        const Eigen::Vector4d clip = to_clip * Eigen::Vector4d(x, y, z, 1.0);
382	        if (clip.w() <= 1e-9)
383	            return std::nullopt; // behind the camera
384	        return ImVec2(float((0.5 + 0.5 * clip.x() / clip.w()) * viewport[2]), float((0.5 - 0.5 * clip.y() / clip.w()) * viewport[3]));
385	    };
386	
387	    Target target;
388	    float x0 = 0, y0 = 0, x1 = 0, y1 = 0;
389	    for (int corner = 0; corner < 8; ++corner) {
390	        const auto point = project(corner & 1 ? box.max.x() : box.min.x(), corner & 2 ? box.max.y() : box.min.y(),
391	                                   corner & 4 ? box.max.z() : box.min.z());
392	        if (!point)
393	            return std::nullopt;
394	        x0 = corner == 0 ? point->x : std::min(x0, point->x);
395	        y0 = corner == 0 ? point->y : std::min(y0, point->y);
396	        x1 = corner == 0 ? point->x : std::max(x1, point->x);
397	        y1 = corner == 0 ? point->y : std::max(y1, point->y);
398	    }
399	    const auto top = project(box.center().x(), box.center().y(), box.max.z());
400	    if (!top)
401	        return std::nullopt;
402	    target.rect     = {x0, y0, x1 - x0, y1 - y0};
403	    target.anchor_x = top->x;
404	    target.anchor_y = top->y;
405	    return target;
406	}
