408	void IssueOverlay::render()
409	{
410	    m_frame = {};
411	    // Without the token file the app keeps OrcaSlicer's stock presentation,
412	    // which has no overlay; the failure was logged when the tokens were read.
413	    const ShellTheme* theme = brand_theme();
414	    if (theme == nullptr)
415	        return;
416	    const PrintIssueSnapshot& snapshot = m_monitor.snapshot();
417	    const ShellMetrics&       m        = theme->metrics();
418	    const float               scale    = wxGetApp().imgui()->get_style_scaling();
419	    const Size                canvas   = m_canvas.get_canvas_size();
420	    const Style style{m, theme->palette(GUI_App::dark_mode()), scale, float(canvas.get_width()), float(canvas.get_height()),
421	                      std::round(m.space_3 * scale), std::round(m.space_3 * scale), std::round(m.space_2 * scale),
422	                      ImGui::GetTextLineHeight(), std::round(m.space_2 * scale), std::round(m.button.icon.width * scale),
423	                      int(std::lround(m.button.icon.icon_size * scale))};
424	
425	    const PrintIssue* open = m_selected.empty() ? nullptr : snapshot.find(m_selected);
426	    if (open != nullptr && open->object != 0) {
427	        if (selection_holds(*open))
428	            m_bound = true;
429	        else if (m_bound)
430	            open = nullptr; // the person let go of the object
431	    }
432	    if (open == nullptr)
433	        m_selected.clear(); // closed, or the native source stopped reporting it
434	    // A list of one is never opened; one that shrank to one closes.
435	    if (snapshot.issues.size() < 2)
436	        m_list_open = false;
437	
438	    watch_for_arrivals(snapshot);
439	    // No issue, no pill: nothing to say is said by saying nothing.
440	    const bool pill_shown = !snapshot.issues.empty();
441	    if (pill_shown)
442	        m_frame.pill_text = status_label(snapshot, tally(snapshot));
443	    m_frame.pill_opens_list = snapshot.issues.size() > 1;
444	
445	    const float pill_w     = !pill_shown ? 0.f :
446	                             style.pad + style.dot + style.gap + ImGui::CalcTextSize(m_frame.pill_text.c_str()).x +
447	                                 (m_frame.pill_opens_list ? style.gap + float(style.icon) : 0.f) + style.pad;
448	    const float row_height = std::round(m.menu_row.height * scale) + style.line; // two lines of text
449	    const float list_height = m_list_open ? float(snapshot.issues.size()) * row_height + 2 * std::round(m.popover.padding_y * scale) : 0.f;
450	    StatusLayout layout = layout_status(style.canvas_w, style.canvas_h, style.inset, style.gap, pill_w,
451	                                        pill_shown ? std::round(m.chip.height * scale) : 0.f,
452	                                        std::round(m.print_issues.list_width * scale), list_height);
453	
454	    if (pill_shown)
455	        draw_pill(style, layout, snapshot);
456	    if (m_list_open)
457	        draw_list(style, layout, snapshot, row_height);
458	    else
459	        draw_notices(style, layout, snapshot); // a docked bubble then starts above them
460	    if (open != nullptr)
461	        draw_bubble(style, layout, snapshot, *open);
462	}
