464	// What OrcaSlicer holds that is not a print problem: the outcome of an action,
465	// or work still running. Each is OrcaSlicer's own words in a panel above the
466	// pill, there for as long as OrcaSlicer holds the notification, with a close
467	// button that closes it the way its own did.
468	void IssueOverlay::draw_notices(const Style& s, StatusLayout& layout, const PrintIssueSnapshot& snapshot)
469	{
470	    // Work that is still running is shown in the chat, where it has its bar
471	    // and its Cancel; here are the outcomes only.
472	    std::vector<Notice> results;
473	    for (const Notice& notice : snapshot.notices)
474	        if (notice.route == NoticeRoute::Result)
475	            results.push_back(notice);
476	    // The newest few; an older one returns when a newer one goes.
477	    constexpr std::size_t kShown = 3;
478	    constexpr int         kLines = 4;
479	    const std::size_t first = results.size() > kShown ? results.size() - kShown : 0;
480	    const float       width = std::round(s.m.print_issues.list_width * s.scale);
481	    const float       wrap  = width - 2 * s.pad - s.dot - s.gap - s.line - s.gap;
482	    std::vector<std::string> texts;
483	    std::vector<float>       heights;
484	    for (std::size_t index = first; index < results.size(); ++index) {
485	        texts.push_back(trimmed(results[index].text));
486	        const float text_h = std::min(ImGui::CalcTextSize(texts.back().c_str(), nullptr, false, wrap).y, kLines * s.line);
487	        heights.push_back(s.pad + text_h + s.pad);
488	    }
489	    const std::vector<OverlayRect> rects = stack_notices(layout, s.inset, s.gap, width, heights);
490	
491	    for (std::size_t slot = 0; slot < rects.size(); ++slot) {
492	        const OverlayRect& rect = rects[slot];
493	        if (rect.empty())
494	            continue;
495	        const Notice& notice = results[first + slot];
496	        const wxColour& dot = notice.level == NoticeLevel::Error ? s.p.status_danger :
497	                              notice.level == NoticeLevel::Warning ? s.p.status_warning :
498	                              notice.route == NoticeRoute::Progress ? s.p.text_secondary : s.p.status_success;
499	        const OverlayRect close{rect.x + rect.w - s.pad - s.line, rect.y + s.pad, s.line, s.line};
500	        m_frame.notices.push_back({notice.kind, rect, close});
501	
502	        begin_bare(("##jusprin_notice_" + std::to_string(slot)).c_str(), rect);
503	        ImDrawList& draw = *ImGui::GetWindowDrawList();
504	        panel(draw, rect, s.p, std::round(s.m.radius_medium * s.scale), s.p.surface_raised);
505	        draw.AddCircleFilled(ImVec2(rect.x + s.pad + s.dot / 2, rect.y + s.pad + s.line / 2), s.dot / 2, im_color(dot));
506	        const ImVec2 text_at(rect.x + s.pad + s.dot + s.gap, rect.y + s.pad);
507	        draw.PushClipRect(text_at, ImVec2(text_at.x + wrap, rect.y + rect.h - s.pad), true);
508	        draw.AddText(ImGui::GetFont(), ImGui::GetFontSize(), text_at, im_color(s.p.text_primary), texts[slot].c_str(), nullptr, wrap);
509	        draw.PopClipRect();
510	        ImGui::SetCursorScreenPos(ImVec2(close.x, close.y));
511	        if (ImGui::InvisibleButton("##close", ImVec2(close.w, close.h)))
512	            after_frame([kind = notice.kind](IssueOverlay& self) { self.m_monitor.dismiss(kind); });
513	        const char*  cross = "\xC3\x97";
514	        const ImVec2 size  = ImGui::CalcTextSize(cross);
515	        draw.AddText(ImVec2(close.x + std::round((close.w - size.x) / 2), close.y + std::round((close.h - size.y) / 2)),
516	                     im_color(ImGui::IsItemHovered() ? s.p.text_primary : s.p.text_secondary), cross);
517	        ImGui::End();
518	    }
519	}
