521	void IssueOverlay::draw_pill(const Style& s, const StatusLayout& layout, const PrintIssueSnapshot& snapshot)
522	{
523	    const OverlayRect& pill = layout.pill;
524	    m_frame.pill = pill;
525	
526	    const Tally t = tally(snapshot);
527	    const wxColour& dot = !snapshot.checked || (t.current == 0 && !snapshot.issues.empty()) ? s.p.text_secondary :
528	                          snapshot.issues.empty() ? s.p.status_success : t.blockers != 0 ? s.p.status_danger : s.p.status_warning;
529	    // The pill reads as held down while what it opened is open.
530	    const bool opened = m_list_open || (!m_frame.pill_opens_list && !m_selected.empty());
531	
532	    begin_bare("##jusprin_issue_pill", pill);
533	    ImDrawList& draw = *ImGui::GetWindowDrawList();
534	    ImGui::SetCursorScreenPos(ImVec2(pill.x, pill.y));
535	    if (ImGui::InvisibleButton("##pill", ImVec2(pill.w, pill.h)))
536	        after_frame([](IssueOverlay& self) { self.press_pill(); });
537	    const bool  hovered = ImGui::IsItemHovered();
538	    const float radius  = std::round(s.m.chip.radius * s.scale);
539	    if (m_announced) {
540	        const float turn = std::chrono::duration<float>(std::chrono::steady_clock::now() - *m_announced) / kAnnouncement * kAnnouncementRings;
541	        if (turn < float(kAnnouncementRings)) {
542	            // Each ring leaves the pill's edge quickly, slows, and fades as it goes.
543	            const float phase  = turn - std::floor(turn);
544	            const float spread = (1 - (1 - phase) * (1 - phase)) * s.gap;
545	            const ImU32 ring   = IM_COL32(dot.Red(), dot.Green(), dot.Blue(), int(std::lround(float(dot.Alpha()) * (1 - phase))));
546	            draw.PushClipRectFullScreen();
547	            draw.AddRect(ImVec2(pill.x - spread, pill.y - spread), ImVec2(pill.x + pill.w + spread, pill.y + pill.h + spread), ring,
548	                         radius + spread, 0, s.m.focus.width * s.scale);
549	            draw.PopClipRect();
550	            m_frame.attention = true;
551	            m_canvas.request_extra_frame(); // until the ring has run
552	        } else {
553	            m_announced.reset();
554	        }
555	    }
556	    panel(draw, pill, s.p, radius, opened ? s.p.surface_selected : hovered ? s.p.surface_subtle : s.p.surface_raised);
557	    draw.AddCircleFilled(ImVec2(pill.x + s.pad + s.dot / 2, pill.y + pill.h / 2), s.dot / 2, im_color(dot));
558	    const ImVec2 size = ImGui::CalcTextSize(m_frame.pill_text.c_str());
559	    draw.AddText(ImVec2(pill.x + s.pad + s.dot + s.gap, pill.y + std::round((pill.h - size.y) / 2)), im_color(s.p.text_primary),
560	                 m_frame.pill_text.c_str());
561	    if (m_frame.pill_opens_list)
562	        // The list opens upward.
563	        icon(draw, m_list_open ? "chevron-down" : "chevron-up", s.icon, pill.x + pill.w - s.pad - float(s.icon),
564	             pill.y + std::round((pill.h - float(s.icon)) / 2), s.p.text_secondary);
565	    ImGui::End();
566	}
