579	    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, std::round(s.m.popover.border_width * s.scale));
580	    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, std::round(s.m.popover.radius * s.scale));
581	    ImGui::PushStyleVar(ImGuiStyleVar_WindowMinSize, ImVec2(0.f, 0.f));
582	    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0.f, 0.f));
