602	        const bool clicked = ImGui::InvisibleButton("##row", ImVec2(ImGui::GetContentRegionAvail().x, row_height));
603	        ImGui::PopID();
604	        const ImVec2 min = ImGui::GetItemRectMin(), max = ImGui::GetItemRectMax();
605	        m_frame.rows.emplace_back(issue.id, OverlayRect{min.x, min.y, max.x - min.x, max.y - min.y});
606	        // The list is a menu: its row under the pointer is a menu row's.
