608	            draw.AddRectFilled(min, max, im_color(s.p.surface_raised_hover), std::round(s.m.menu_row.radius * s.scale));
609	        draw.AddCircleFilled(ImVec2(min.x + s.pad / 2 + s.dot / 2, (min.y + max.y) / 2), s.dot / 2, im_color(tone(issue, s.p)));
610	        const float text_x = min.x + s.pad / 2 + s.dot + s.gap;
