612	        const std::string where = (issue.object_name.empty() ? plate_label() : issue.object_name) +
613	                                  (issue.ignored ? " \xC2\xB7 " + ignored_label() : std::string()) +
614	                                  (issue.stale ? " \xC2\xB7 " + checking_label() : std::string());
615	        draw.PushClipRect(ImVec2(text_x, min.y), ImVec2(max.x - s.gap, max.y), true);
