628	void IssueOverlay::draw_bubble(const Style& s, const StatusLayout& layout, const PrintIssueSnapshot& snapshot, const PrintIssue& issue)
629	{
630	    // The pager walks every issue that counts, in the list's order, so the
631	    // list need not be opened again to reach the next one. An ignored warning
632	    // is not on that walk.
633	    std::vector<const PrintIssue*> walk;
634	    if (!issue.ignored)
635	        for (const PrintIssue& other : snapshot.issues)
636	            if (!other.ignored)
637	                walk.push_back(&other);
638	    const int  walk_index = int(std::find(walk.begin(), walk.end(), &issue) - walk.begin());
639	    const bool paged      = walk.size() > 1;
640	    const bool ignorable  = issue.severity == IssueSeverity::Warning;
641	
642	    const std::optional<Target> target = target_of(issue);
643	    const bool in_view = target && target->anchor_x >= 0 && target->anchor_x <= s.canvas_w && target->anchor_y >= 0 &&
644	                         target->anchor_y <= s.canvas_h;
645	    const bool busy    = m_actions.chat_busy && m_actions.chat_busy();
646	    const bool enabled = snapshot.checked && !issue.stale && !busy;
647	    // Looked at every frame: the window that sets the agent up closes back
648	    // onto this bubble, and the next frame draws what is true then.
649	    const bool ready   = !m_actions.agent_ready || m_actions.agent_ready();
650	
651	    const std::string severity = issue.stale ? checking_label() : issue.ignored ? ignored_label() :
652	                                 issue.severity == IssueSeverity::Blocker ? _u8L("Blocks printing") : _u8L("Warning");
653	    const std::string where    = issue.object == 0 ? plate_label() :
654	                                 issue.object_name + (target && !in_view ? " \xC2\xB7 " + _u8L("out of view") : std::string());
655	    const std::string message  = trimmed(issue.message);
656	    const std::string pager    = paged ? format(_u8L("%1% of %2%"), walk_index + 1, walk.size()) : std::string();
657	    const std::string note     = busy ? _u8L("The assistant is replying...") : std::string();
658	    const std::string ignore   = !ignorable ? std::string() : issue.ignored ? _u8L("Stop ignoring") : _u8L("Ignore this warning");
659	
660	    const float width = std::round(s.m.print_issues.bubble_width * s.scale);
661	    const float wrap  = width - 2 * s.pad;
662	    const ImVec2 message_size = ImGui::CalcTextSize(message.c_str(), nullptr, false, wrap);
663	    // One button across the bubble, sized by padding around its label.
664	    const ButtonRecipe& recipe   = s.m.button.primary;
665	    const float         button_h = std::round(s.line + 2 * recipe.padding_y * s.scale);
666	    // Under the button: the lesser action on the left, the pager on the right.
667	    const float footer_h = paged ? s.icon_button : ignorable ? s.line : 0.f;
668	
669	    BubbleRequest request;
670	    request.canvas_w    = s.canvas_w;
671	    request.canvas_h    = s.canvas_h;
672	    request.inset       = s.inset;
673	    request.leader      = std::round(s.m.space_4 * s.scale);
674	    request.pad         = s.pad;
675	    request.bubble_w    = width;
676	    request.bubble_h    = s.pad + s.line + s.gap + message_size.y + (note.empty() ? 0 : s.gap + s.line) + s.pad + button_h +
677	                          (footer_h > 0 ? s.gap + footer_h : 0) + s.pad;
678	    request.has_target  = in_view;
679	    request.dock_right  = layout.dock_right;
680	    request.dock_bottom = layout.dock_bottom;
681	    request.taken       = {layout.pill};
682	    for (const IssueOverlayFrame::NoticeFrame& notice : m_frame.notices)
683	        request.taken.push_back(notice.rect);
684	    if (in_view) {
685	        request.target   = target->rect;
686	        request.anchor_x = target->anchor_x;
687	        request.anchor_y = target->anchor_y;
688	    }
689	    if (!m_canvas.get_selection().is_empty()) {
690	        const StripRect strip = layout_tool_strip(tool_strip_geometry(s.m), s.scale, s.canvas_w, s.canvas_h).strip;
691	        request.taken.push_back({strip.x, strip.y, strip.w, strip.h});
692	    }
693	    const BubblePlacement placement = place_bubble(request);
694	    const OverlayRect&    bubble    = placement.rect;
695	
696	    m_frame.bubble          = true;
697	    m_frame.side            = placement.side;
698	    m_frame.target_in_view  = in_view;
699	    m_frame.bubble_rect     = bubble;
700	    m_frame.issue_id        = issue.id;
701	    m_frame.pager_index     = walk_index;
702	    m_frame.pager_size      = int(walk.size());
703	    m_frame.actions_enabled = enabled;
704	    if (target) {
705	        m_frame.anchor_x = target->anchor_x;
706	        m_frame.anchor_y = target->anchor_y;
707	    }
708	
709	    begin_bare("##jusprin_issue_bubble", bubble);
710	    ImDrawList& draw = *ImGui::GetWindowDrawList();
711	    draw.PushClipRectFullScreen();
712	    if (placement.side != BubbleSide::Docked) {
713	        // The leader: from the bubble's nearest edge to the object.
714	        const ImVec2 to(placement.leader_to_x, placement.leader_to_y);
715	        draw.AddLine(ImVec2(placement.leader_from_x, placement.leader_from_y), to, im_color(tone(issue, s.p)), 2.f * s.scale);
