182	void ViewportToolStrip::run_after_frame(StripTool tool, const StripRect& button)
183	{
184	    wxGetApp().CallAfter([self = std::weak_ptr<ViewportToolStrip*>(m_self), tool, button]() {
185	        if (const auto strip = self.lock())
186	            (*strip)->run(tool, button);
187	    });
188	}
189	
190	void ViewportToolStrip::run(StripTool tool, const StripRect& button)
191	{
192	    switch (tool) {
193	    case StripTool::Move:
194	    case StripTool::Rotate:
195	    case StripTool::Scale:
196	        m_controller.toggle_tool(gizmo_for(tool));
197	        break;
198	    case StripTool::Duplicate:
199	        wxGetApp().plater()->increase_instances(1);
200	        break;
201	    case StripTool::More: {
202	        // The canvas's own right-click path, so the menu matches the
203	        // selection exactly as it does on a right-click over the object. It
204	        // opens below the button, from its left edge. Plater expects logical
205	        // coordinates; ImGui's are device pixels on Retina.
206	        const double retina = m_canvas.get_scale();
207	        const Vec2d anchor(button.x / retina, (button.y + button.h) / retina);
208	        m_canvas.post_event(RBtnEvent(EVT_GLCANVAS_RIGHT_CLICK, {anchor, false}));
209	        break;
210	    }
211	    }
212	}
