436	void HeaderButton::draw(wxDC& dc, wxGraphicsContext& context, const wxSize& client)
437	{
438	    const auto& p = m_theme.palette(m_dark);
439	    const bool primary = m_style == HeaderStyle::PrimaryLeft || m_style == HeaderStyle::PrimaryRight;
440	    const bool chip    = m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight;
441	    const wxColour& ground = m_surface == HeaderSurface::Raised ? p.surface_raised : p.surface_canvas;
442	    dc.SetBackground(wxBrush(m_style == HeaderStyle::Menu ? p.surface_raised : ground));
443	    dc.Clear();
444	    wxGraphicsContext* gc = &context;
445	
446	    // A row that states a warning stays readable when it cannot be invoked:
447	    // its words are the warning, not a greyed-out choice.
448	    const bool informational = m_decoration.sub_label_tone != StatusTone::None;
449	    const auto foreground = !IsEnabled() && !informational ? p.action_disabled_text :
450	                            m_decoration.danger ? p.status_danger :
451	                            primary ? p.action_primary_text :
452	                            m_style == HeaderStyle::Quiet ? p.text_secondary : p.text_primary;
453	    const bool highlighted = (m_hover || m_open || m_menu_selected) && IsEnabled();
454	    wxColour fill = primary ? (!IsEnabled() ? p.action_disabled : m_pressed || m_open ? p.action_primary_pressed :
455	                              m_hover ? p.action_primary_hover : p.action_primary) :
456	                   // A menu row under the pointer or the keyboard is the design
457	                   // system's Menu/Row band; every other control shows its open
458	                   // or hovered state as selected.
459	                   highlighted ? (m_style == HeaderStyle::Menu ? p.surface_raised_hover : p.surface_selected) :
460	                   // The filament half sits on a quieter ground than the printer
461	                   // half, so the chip reads as two things inside one outline.
462	                   m_style == HeaderStyle::ChipRight ? p.surface_subtle :
463	                   m_style == HeaderStyle::Menu ? p.surface_raised : ground;
464	
465	    const ShellMetrics& m = m_theme.metrics();
466	    const double w = client.x, h = client.y;
467	    const double r = FromDIP(primary ? m.radius_medium :
468	                             chip ? m.chip.radius :
469	                             m_style == HeaderStyle::Menu ? m.menu_row.radius :
470	                             m_style == HeaderStyle::Outline ? m.button.icon.radius : m.radius_small);
471	    // Outlines take whole-pixel coordinates: wx itself moves a 1 px pen half a
472	    // pixel onto the grid, and a second half-pixel move blurred them at 1x.
473	    if (chip) {
474	        // Each half draws the whole chip's rounded rectangle, extended past
475	        // the shared inner edge so only its own outer corners round. The top
476	        // and bottom borders then meet exactly across the seam.
477	        gc->SetPen(wxPen(p.border_subtle));
478	        gc->SetBrush(wxBrush(fill));
479	        gc->DrawRoundedRectangle(m_style == HeaderStyle::ChipLeft ? 0 : -r, 0, w - 1 + r, h - 1, r);
480	        if (m_style == HeaderStyle::ChipRight) {
481	            gc->SetPen(wxPen(p.border_subtle));
482	            gc->StrokeLine(0, 0, 0, h - 1);
483	        }
484	    } else {
485	        const bool outlined = !(primary || m_style == HeaderStyle::Quiet || m_style == HeaderStyle::Menu);
486	        gc->SetPen(outlined ? wxPen(p.border_subtle) : *wxTRANSPARENT_PEN);
487	        gc->SetBrush(wxBrush(fill));
488	        // A fill without a pen is not moved, so it keeps its half-pixel inset.
489	        const double inset = outlined ? 0 : 0.5;
490	        // A split half extends past its shared inner edge, as the chip halves
491	        // do, so only its outer corners round and its top and bottom edges
