1	// A project skill is text for one kind of situation. The page writes each one
2	// as skills/<name>/SKILL.md: YAML frontmatter, then the body, which is the
3	// text the model gets. A skill with a `trigger` is added by the app to one
4	// request when the event it names happens; the model does not choose it. A
5	// skill with a `description` is listed for the model, which reads it with
6	// skill_read when the description fits. A skill may have both.
7	export interface Skill {
8	  name: string;
9	  trigger?: string;
10	  description?: string;
11	  text: string;
12	}
13	
14	const SKILL_NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
15	const TRIGGER = /^[a-z]+(?:_[a-z]+)*$/;
16	const FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;
17	// The app refuses a longer text (AgentHost, Protocol::kSkills).
18	export const SKILL_TEXT_LIMIT = 16 * 1024;
19	const encoder = new TextEncoder();
20	
21	function scalar(raw: string, source: string): string {
22	  if (raw.startsWith('"')) {
23	    try {
24	      const value: unknown = JSON.parse(raw);
25	      if (typeof value === 'string') return value;
26	    } catch {
27	      // Report one stable frontmatter error below.
28	    }
29	    throw new Error(`${source}: invalid quoted frontmatter value`);
30	  }
31	  if (raw.startsWith("'")) {
32	    if (!raw.endsWith("'") || raw.length < 2)
33	      throw new Error(`${source}: invalid quoted frontmatter value`);
34	    return raw.slice(1, -1).replace(/''/g, "'");
35	  }
36	  if (raw.endsWith('"') || raw.endsWith("'"))
37	    throw new Error(`${source}: invalid quoted frontmatter value`);
38	  return raw;
39	}
40	
41	export function parseSkill(text: string, source: string): Skill {
42	  const match = text.match(FRONTMATTER);
43	  if (!match) throw new Error(`${source}: SKILL.md must start with YAML frontmatter`);
44	
45	  const fields = new Map<string, string>();
46	  for (const line of match[1].split(/\r?\n/)) {
47	    const separator = line.indexOf(':');
48	    if (separator < 1) throw new Error(`${source}: invalid frontmatter line`);
49	    const key = line.slice(0, separator).trim();
50	    const raw = line.slice(separator + 1).trim();
51	    if (!['name', 'trigger', 'description'].includes(key) || fields.has(key) || !raw)
52	      throw new Error(`${source}: frontmatter must contain only name, trigger and description`);
53	    fields.set(key, scalar(raw, source));
54	  }
55	
56	  const name = fields.get('name') ?? '';
57	  const trigger = fields.get('trigger');
58	  const description = fields.get('description');
59	  const directory = source.replace(/\\/g, '/').split('/').at(-2) ?? '';
60	  if (!SKILL_NAME.test(name) || name.length > 64 || name !== directory)
61	    throw new Error(`${source}: name must match its lowercase hyphenated directory`);
62	  if (trigger === undefined && description === undefined)
63	    throw new Error(`${source}: a skill needs a trigger, a description or both`);
64	  if (trigger !== undefined && (!TRIGGER.test(trigger) || trigger.length > 64))
65	    throw new Error(`${source}: trigger must be lowercase words joined by underscores`);
66	  if (description !== undefined && (/[\r\n]/.test(description) || encoder.encode(description).length > 300))
67	    throw new Error(`${source}: description must be one line of at most 300 UTF-8 bytes`);
68	
69	  const body = text.slice(match[0].length).replace(/^(?:\r?\n)+/, '').trimEnd();
70	  if (!body) throw new Error(`${source}: skill body is empty`);
71	  if (encoder.encode(body).length > SKILL_TEXT_LIMIT)
72	    throw new Error(`${source}: skill body exceeds 16 KiB`);
73	
74	  return {
75	    name,
76	    ...(trigger === undefined ? {} : { trigger }),
77	    ...(description === undefined ? {} : { description }),
78	    text: body,
79	  };
80	}
81	
82	// Sorted by name, as the app expects them; at most one skill per trigger,
83	// since the app adds the one its event names.
84	export function loadSkills(files: Record<string, string>): Skill[] {
85	  const skills = Object.entries(files).map(([source, text]) => parseSkill(text, source));
86	  skills.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0);
87	  for (let index = 1; index < skills.length; index += 1)
88	    if (skills[index - 1].name === skills[index].name)
89	      throw new Error(`duplicate skill name: ${skills[index].name}`);
90	  const triggers = new Set<string>();
91	  for (const skill of skills) {
92	    if (skill.trigger === undefined) continue;
93	    if (triggers.has(skill.trigger)) throw new Error(`two skills share the trigger ${skill.trigger}`);
94	    triggers.add(skill.trigger);
95	  }
96	  return skills;
97	}
