218	bool PreferencesWindow::on_page_message(const std::string& type, const json& payload)
219	{
220	    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "close") {
221	        CallAfter([this] { close_for({}); });
222	        return true;
223	    }
224	    if (type != Agent::Protocol::kPreferencesAction)
225	        return false;
226	    const Outcome outcome = apply_action(*wxGetApp().app_config, payload);
227	    if (!outcome.error.empty())
228	        BOOST_LOG_TRIVIAL(warning) << "JusPrin Preferences refused an action: " << outcome.error;
229	    // The page draws what is stored, so a refused change springs back.
230	    push_state();
231	    if (outcome.error.empty() && outcome.effect != Effect::None) {
232	        // Not from inside the web view's message handler: some of these open
233	        // a modal dialog or close this window.
234	        CallAfter([this, outcome] { carry_out(outcome); });
235	    }
236	    return true;
237	}
