23	void load_icon(GLTexture& texture, const std::string& name, int size_px)
24	{
25	    const boost::filesystem::path path = boost::filesystem::path(resources_dir()) / "jusprin" / "ui" / "icons" / (name + ".svg");
26	    boost::nowide::ifstream file(path.string());
27	    if (!file.is_open())
28	        throw std::runtime_error("canvas icon is missing: " + path.string());
29	    std::string svg((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
30	    // The icons are drawn in currentColor for the web pages; nanosvg reads that as grey.
31	    boost::replace_all(svg, "currentColor", "#FFFFFF");
32	
33	    std::unique_ptr<NSVGimage, decltype(&nsvgDelete)> image(nsvgParse(svg.data(), "px", 96.0f), nsvgDelete);
34	    if (image == nullptr || image->width <= 0.f)
35	        throw std::runtime_error("canvas icon could not be parsed: " + path.string());
36	    std::unique_ptr<NSVGrasterizer, decltype(&nsvgDeleteRasterizer)> rasterizer(nsvgCreateRasterizer(), nsvgDeleteRasterizer);
37	    std::vector<unsigned char> pixels(size_t(size_px) * size_px * 4, 0);
38	    nsvgRasterize(rasterizer.get(), image.get(), 0, 0, float(size_px) / image->width, pixels.data(), size_px, size_px, size_px * 4);
39	
40	    texture.reset();
41	    if (!texture.load_from_raw_data(std::move(pixels), size_px, size_px))
42	        throw std::runtime_error("canvas icon could not be uploaded: " + path.string());
43	}
