// Records one Bambu model as installed in a scratch data folder, keeping the file's checksum valid.
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const path = process.argv[2];
const raw = readFileSync(path, 'utf8');
const conf = JSON.parse(raw.slice(0, raw.lastIndexOf('#')));
conf.models = [...(conf.models ?? []), { vendor: 'BBL', model: 'Bambu Lab A1 mini', nozzle_diameter: '0.4' }];
const text = JSON.stringify(conf, null, '\t') + '\n';
const md5 = createHash('md5').update(text, 'latin1').digest('hex').toUpperCase();
writeFileSync(path, text + `# MD5 checksum ${md5}\n`, 'latin1');
console.log('conf updated', JSON.stringify(conf.models));

