24	// A picture or file is sent in one of two shapes: a data URL (Responses) or a
25	// base64 source with its bytes under "data" (Anthropic).
26	json without_file_bytes(const json& value)
27	{
28	    const auto note = [](const std::string& bytes) { return "[" + std::to_string(bytes.size()) + " characters left out]"; };
29	    if (value.is_string()) {
30	        const std::string& text = value.get_ref<const std::string&>();
31	        return text.rfind("data:", 0) == 0 && text.find(";base64,") != std::string::npos ? json(note(text)) : value;
32	    }
33	    if (value.is_array()) {
34	        json copy = json::array();
35	        for (const json& child : value)
36	            copy.push_back(without_file_bytes(child));
37	        return copy;
38	    }
39	    if (!value.is_object())
40	        return value;
41	    const bool base64 = value.value("type", json()) == "base64";
42	    json       copy   = json::object();
43	    for (auto it = value.begin(); it != value.end(); ++it)
44	        copy[it.key()] = base64 && it.key() == "data" && it.value().is_string() ? json(note(it.value().get<std::string>())) :
45	                                                                                  without_file_bytes(it.value());
46	    return copy;
47	}
