49	void keep_newest(const std::filesystem::path& directory, std::size_t keep)
50	{
51	    std::error_code                    ec;
52	    std::vector<std::filesystem::path> files;
53	    for (std::filesystem::directory_iterator it(directory, ec), end; !ec && it != end; it.increment(ec))
54	        files.push_back(it->path());
55	    if (files.size() <= keep)
56	        return;
57	    // The names start with the time, so name order is age order.
58	    std::sort(files.begin(), files.end());
59	    for (std::size_t i = 0; i + keep < files.size(); ++i)
60	        std::filesystem::remove(files[i], ec);
61	}
