80	std::function<void(const SentRequest&)> request_log_writer(std::filesystem::path directory, std::size_t keep)
81	{
82	    return [directory = std::move(directory), keep](const SentRequest& sent) {
83	        // Two agents can post in the same millisecond: a title beside a reply.
84	        static std::atomic<unsigned> counter{0};
85	        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
86	        char       name[40];
87	        std::snprintf(name, sizeof name, "%013lld-%06u.json", static_cast<long long>(now.count()), ++counter % 1000000u);
88	        std::error_code ec;
89	        std::filesystem::create_directories(directory, ec);
90	        std::ofstream file(directory / name, std::ios::binary);
91	        file << json{{"provider", sent.provider},
92	                     {"chat", sent.chat_key},
93	                     {"turn", sent.turn_id},
94	                     {"sequence", sent.sequence},
95	                     {"body", without_file_bytes(sent.body)}}
96	                    .dump();
97	        file.close();
98	        if (!file) {
99	            BOOST_LOG_TRIVIAL(warning) << "Agent request log not written in " << directory.string();
100	            return;
101	        }
102	        keep_newest(directory, keep);
103	    };
104	}
