106	AgentServicePtr make_provider_agent(const ProviderProfile&               profile,
107	                                    const std::string&                   api_key,
108	                                    const std::string&                   model,
109	                                    const std::string&                   endpoint,
110	                                    std::unique_ptr<IAgentHttpTransport> transport,
111	                                    ProviderListeners                    listeners)
112	{
113	    ProviderAgentConfig config;
114	    config.profile = profile;
