133	AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
134	                                   const std::string&                                           endpoint_override,
135	                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
136	                                   ProviderListeners                                            listeners)
137	{
138	    AgentRuntime runtime;
139	    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
140	    if (!settings.enabled) {
141	        runtime.unavailable_reason = "The Agent is not enabled.";
142	        return runtime;
143	    }
144	    const ProviderProfile* profile = profile_for(runtime.provider);
145	    if (profile == nullptr) {
146	        runtime.unavailable_reason = "The configured Agent provider is not supported.";
147	        return runtime;
148	    }
149	    if (!settings.cloud_consent) {
150	        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
151	        return runtime;
152	    }
153	    if (settings.api_key.empty()) {
154	        runtime.unavailable_reason = profile->account_sign_in ? "Not signed in to a JusPrin account." :
155	                                                                "No " + profile->display_name + " API key is configured.";
156	        return runtime;
157	    }
158	    if (profile->account_sign_in) {
159	        const std::optional<ProviderProfile> served =
160	            account_profile(*profile, endpoint_override.empty() ? settings.endpoint : endpoint_override, settings.format);
161	        if (!served) {
162	            runtime.unavailable_reason = "Sign in to your JusPrin account again.";
163	            return runtime;
164	        }
165	        runtime.service = make_provider_agent(*served, settings.api_key, settings.model, {}, transport(), std::move(listeners));
166	    } else {
167	        runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
168	                                              std::move(listeners));
169	    }
170	    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
171	    if (runtime.availability == AgentAvailability::Unavailable)
172	        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
173	    return runtime;
174	}
