// Points a scratch data folder at Sonnet 5.5, taking the Anthropic key from the main JusPrin settings. Prints no key.
//   node conf-sonnet.mjs <scratch conf>         adds the agent settings
//   node conf-sonnet.mjs <scratch conf> --wipe  removes the key again
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const path = process.argv[2];
const read = (p) => { const raw = readFileSync(p, 'latin1'); return JSON.parse(raw.slice(0, raw.lastIndexOf('#'))); };
const conf = read(path);
if (process.argv[3] === '--wipe') {
  delete conf.jusprin_agent;
} else {
  const key = read(`${process.env.APPDATA}/JusPrin2/JusPrin2.conf`).jusprin_agent.anthropic_api_key;
  if (!key) throw new Error('no Anthropic key in the main settings');
  conf.jusprin_agent = { anthropic_api_key: key, provider: 'anthropic', model: 'claude-sonnet-5-5', enabled: 'true', cloud_consent: 'true' };
}
const text = JSON.stringify(conf, null, '\t') + '\n';
const md5 = createHash('md5').update(text, 'latin1').digest('hex').toUpperCase();
writeFileSync(path, text + `# MD5 checksum ${md5}\n`, 'latin1');
console.log(process.argv[3] === '--wipe' ? 'key removed' : 'agent settings written: anthropic / claude-sonnet-5-5');

// Summarises the app's request log: which model, which skills, and what each request carried.
//   node reqdump.mjs <dir> [--full <outdir>]
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const dir = process.argv[2];
const full = process.argv[3] === '--full' ? process.argv[4] : null;
if (full) mkdirSync(full, { recursive: true });
for (const name of readdirSync(dir).sort()) {
  const r = JSON.parse(readFileSync(`${dir}/${name}`, 'utf8'));
  const b = r.body;
  const sys = typeof b.system === 'string' ? b.system : JSON.stringify(b.system ?? '');
  console.log(`\n=== ${name} provider=${r.provider} chat=${r.chat} turn=${r.turn} seq=${r.sequence}`);
  console.log(`model=${b.model} max_tokens=${b.max_tokens} thinking=${JSON.stringify(b.thinking ?? null)} effort=${JSON.stringify(b.output_config ?? null)} tools=${(b.tools ?? []).length} systemChars=${sys.length} messages=${(b.messages ?? []).length}`);
  (b.messages ?? []).forEach((m, i) => {
    const parts = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
    parts.forEach((p, j) => {
      const text = p.type === 'text' ? p.text : p.type === 'tool_use' ? `${p.name} ${JSON.stringify(p.input)}` : p.type === 'tool_result' ? JSON.stringify(p.content) : JSON.stringify(p).slice(0, 120);
      console.log(`  [${i}.${j}] ${m.role} ${p.type} ${text.length} chars: ${text.slice(0, 160).replace(/\s+/g, ' ')}`);
    });
  });
  if (full) writeFileSync(`${full}/${name}`, JSON.stringify(b, null, 1));
}

