// One step of the real chat: tap a reply button or type a message, wait for the turn to end, print the page.
//   node turn.mjs tap "<button text>" | node turn.mjs say "<message>" | node turn.mjs read
const [, , mode, arg] = process.argv;
const targets = await (await fetch('http://127.0.0.1:9333/json/list')).json();
const page = targets.find((t) => t.type === 'page' && t.url.includes('agent/index.html') && !t.url.includes('panel='));
const socket = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => socket.addEventListener('open', r));
let next = 0;
const call = (method, params = {}) => new Promise((resolve, reject) => {
  const id = ++next;
  const on = (e) => { const m = JSON.parse(e.data); if (m.id !== id) return; socket.removeEventListener('message', on);
    m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); };
  socket.addEventListener('message', on);
  socket.send(JSON.stringify({ id, method, params }));
});
const ev = async (expression) => (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
if (mode === 'tap') {
  const hit = await ev(`(() => { const b = [...document.querySelectorAll('button')].filter((x) => x.innerText.trim() === ${JSON.stringify(arg)}).pop(); if (!b) return false; b.click(); return true; })()`);
  if (!hit) { console.log('no button', arg); process.exit(2); }
} else if (mode === 'say') {
  await ev("document.querySelector('textarea').focus()");
  await call('Input.insertText', { text: arg });
  for (const t of ['keyDown', 'keyUp'])
    await call('Input.dispatchKeyEvent', { type: t, key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: t === 'keyDown' ? '\r' : undefined });
}
const busy = () => ev(`!!document.querySelector('[aria-label*="Stop" i]')`);
const body = () => ev('document.body.innerText');
if (mode !== 'read') {
  await sleep(3000);
  let last = '', still = 0;
  const started = Date.now();
  while (Date.now() - started < 420000) {
    await sleep(4000);
    const now = await body();
    still = now === last && !(await busy()) ? still + 1 : 0;
    last = now;
    if (still >= 3) break;
  }
  console.log('seconds:', Math.round((Date.now() - started) / 1000));
}
console.log(await body());
socket.close();
process.exit(0);

// Walks the app's request log in order: for the newest request of each model reply, prints new tool calls, results and text.
import { readdirSync, readFileSync } from 'node:fs';
const dir = process.argv[2];
const files = readdirSync(dir).sort();
const seen = new Set();
const cap = Number(process.argv[3] ?? 700);
for (const name of files) {
  const r = JSON.parse(readFileSync(`${dir}/${name}`, 'utf8'));
  const b = r.body;
  console.log(`\n=== ${name} model=${b.model} turn=${String(r.turn).slice(-22)} seq=${r.sequence} messages=${b.messages?.length}`);
  (b.messages ?? []).forEach((m) => {
    const parts = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
    for (const p of parts) {
      const key = JSON.stringify([m.role, p.type, p.text ?? p.id ?? p.tool_use_id ?? p.source?.data]);
      if (seen.has(key)) continue;
      seen.add(key);
      if (p.type === 'text') console.log(`  ${m.role} TEXT (${p.text.length}): ${p.text.slice(0, m.role === 'system' ? 200 : cap).replace(/\s+/g, ' ')}`);
      else if (p.type === 'tool_use') console.log(`  CALL ${p.name} ${JSON.stringify(p.input).slice(0, cap)}`);
      else if (p.type === 'tool_result') console.log(`  RESULT ${JSON.stringify(p.content).slice(0, cap)}`);
      else console.log(`  ${m.role} ${p.type}`);
    }
  });
}

