253	void PrintIssueMonitor::rebuild()
254	{
255	    ++m_rebuilds;
256	    PrintIssueSnapshot next;
257	    next.session    = m_plater.project_state_session();
258	    next.generation = m_snapshot.generation;
259	    if (next.session != m_snapshot.session) {
260	        // Another project: nothing read from the last one describes it.
261	        m_failures.clear();
262	        m_validation.clear();
263	        m_result = {};
264	        m_ignored.clear();
265	    }
266	
267	    const std::vector<Notice> notices = held();
268	    for (const Notice& notice : notices)
269	        if ((notice.route == NoticeRoute::Result || notice.route == NoticeRoute::Progress) && !notice.text.empty())
270	            next.notices.push_back(notice);
271	
272	    PartPlate* plate = m_plater.get_partplate_list().get_curr_plate();
273	    Print*     print = plate != nullptr ? plate->fff_print() : nullptr;
274	    if (plate != nullptr && print != nullptr && m_plater.printer_technology() == ptFFF) {
275	        next.plate   = plate->id().id;
276	        next.slicing = m_plater.is_background_process_slicing();
277	        next.sliced  = plate->is_slice_result_valid();
278	        // A slice that started replaces whatever the last one failed with.
279	        if ((next.slicing && !m_was_slicing) || next.sliced)
280	            m_failures.erase(next.plate);
281	        m_was_slicing = next.slicing;
282	
283	        // OrcaSlicer applies an edit to the print on a short timer. Until it
284	        // has, the print and the notifications describe the project as it
285	        // was, so nothing read from them is current.
286	        next.checked = !m_plater.is_background_process_update_scheduled();
287	        if (next.checked) {
288	            std::vector<PrintIssue> found;
289	            find_placement(*plate, notices, found);
290	            find_validation(*plate, *print, notices, found);
291	            if (holds(notices, NotificationType::SlicingWarning))
292	                find_steps(*plate, *print, found);
293	            read_result(*plate, *print, found);
294	            read_failure(*plate, found);
295	            next.issues = issues_from(notices, std::move(found), next.plate);
296	        } else {
297	            // What it last said, kept and marked: not vouched for, not gone.
298	            // An object that no longer exists has no issue to keep.
299	            std::set<std::uint64_t> objects, instances;
300	            for (const ModelObject* object : m_plater.model().objects) {
301	                objects.insert(object->id().id);
302	                for (const ModelInstance* instance : object->instances)
303	                    instances.insert(instance->id().id);
304	            }
305	            for (PrintIssue issue : m_snapshot.issues) {
306	                if (issue.plate != next.plate || (issue.object != 0 && objects.count(issue.object) == 0) ||
307	                    (issue.instance != 0 && instances.count(issue.instance) == 0))
308	                    continue;
309	                issue.stale = true;
310	                next.issues.push_back(std::move(issue));
311	            }
312	        }

380	// OrcaSlicer's own validation of the print, asked again for the object and
381	// the setting its notification does not carry. It holds one error and one
382	// warning at most; a later check overwrites an earlier warning.
383	void PrintIssueMonitor::find_validation(PartPlate& plate, Print& print, const std::vector<Notice>& held, std::vector<PrintIssue>& found)
384	{
385	    if (!holds(held, NotificationType::ValidateError) && !holds(held, NotificationType::ValidateWarning)) {
386	        m_validation.clear();
387	        return;
388	    }
389	    // While a slice runs the print was valid when it started and any edit
390	    // that invalidates it would have stopped it, so the last answer stands.
391	    if (!m_plater.is_background_process_slicing()) {
392	        const auto started = std::chrono::steady_clock::now();
393	        StringObjectException warning{};
394	        Polygons              polygons;
395	        std::vector<std::pair<Polygon, float>> height_polygons;
396	        // As BackgroundSlicingProcess::validate does before it asks.
397	        print.is_BBL_printer() = wxGetApp().preset_bundle->is_bbl_vendor();
398	        StringObjectException error = print.validate(&warning, &polygons, &height_polygons);
399	        if (!error.string.empty())
400	            m_plater.post_process_string_object_exception(error);
401	        m_last_validate_ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - started).count();
402	        ++m_validate_runs;
403	
404	        m_validation.clear();
405	        const auto add = [&](const StringObjectException& result, bool blocker) {
406	            if (result.string.empty())
407	                return;
408	            PrintIssue issue;
409	            issue.source   = IssueSource::Validation;
410	            issue.severity = blocker ? IssueSeverity::Blocker : IssueSeverity::Warning;
411	            issue.code     = check_name(result.type);
412	            issue.setting  = result.opt_key;
413	            issue.message  = result.string;
414	            issue.plate    = plate.id().id;
415	            issue.answers  = int(blocker ? NotificationType::ValidateError : NotificationType::ValidateWarning);
416	            set_target(issue, result.object);
417	            issue.id = std::string("validation:") + (blocker ? "error" : "warning") + ":" + issue.setting + ":" + target_key(issue);
418	            m_validation.push_back(std::move(issue));
419	        };
420	        add(error, true);
421	        add(warning, false);
422	    }
423	    found.insert(found.end(), m_validation.begin(), m_validation.end());
424	}
