// Removes every copy of the Anthropic key from the scratch data folders, and reports any file still holding it. Prints no key.
import { readFileSync, readdirSync, statSync, writeFileSync, rmSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
const main = readFileSync(`${process.env.APPDATA}/JusPrin2/JusPrin2.conf`, 'latin1');
const key = JSON.parse(main.slice(0, main.lastIndexOf('#'))).jusprin_agent.anthropic_api_key;
const walk = (d) => readdirSync(d).flatMap((n) => { const p = join(d, n); const s = statSync(p); return s.isDirectory() ? walk(p) : s.size < 50e6 ? [p] : []; });
const holding = (d) => walk(d).filter((p) => readFileSync(p, 'latin1').includes(key));
for (const d of process.argv.slice(2)) {
  for (const p of holding(d)) {
    if (p.endsWith('JusPrin2.conf')) {
      const raw = readFileSync(p, 'latin1');
      const conf = JSON.parse(raw.slice(0, raw.lastIndexOf('#')));
      delete conf.jusprin_agent;
      const text = JSON.stringify(conf, null, '\t') + '\n';
      writeFileSync(p, text + `# MD5 checksum ${createHash('md5').update(text, 'latin1').digest('hex').toUpperCase()}\n`, 'latin1');
      console.log('key removed from', p);
    } else {
      rmSync(p);
      console.log('deleted copy', p);
    }
  }
  console.log(d, 'files still holding the key:', holding(d).length);
}

