1	// One step of the real chat: tap a reply button or type a message, wait for the turn to end, print the page.
2	//   node turn.mjs tap "<button text>" | node turn.mjs say "<message>" | node turn.mjs read
3	const [, , mode, arg] = process.argv;
4	const targets = await (await fetch('http://127.0.0.1:9333/json/list')).json();
5	const page = targets.find((t) => t.type === 'page' && t.url.includes('agent/index.html') && !t.url.includes('panel='));
6	const socket = new WebSocket(page.webSocketDebuggerUrl);
7	await new Promise((r) => socket.addEventListener('open', r));
8	let next = 0;
9	const call = (method, params = {}) => new Promise((resolve, reject) => {
10	  const id = ++next;
11	  const on = (e) => { const m = JSON.parse(e.data); if (m.id !== id) return; socket.removeEventListener('message', on);
12	    m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); };
13	  socket.addEventListener('message', on);
14	  socket.send(JSON.stringify({ id, method, params }));
15	});
16	const ev = async (expression) => (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
17	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
18	if (mode === 'tap') {
19	  const hit = await ev(`(() => { const b = [...document.querySelectorAll('button')].filter((x) => x.innerText.trim() === ${JSON.stringify(arg)}).pop(); if (!b) return false; b.click(); return true; })()`);
20	  if (!hit) { console.log('no button', arg); process.exit(2); }
21	} else if (mode === 'say') {
22	  await ev("document.querySelector('textarea').focus()");
23	  await call('Input.insertText', { text: arg });
24	  for (const t of ['keyDown', 'keyUp'])
25	    await call('Input.dispatchKeyEvent', { type: t, key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: t === 'keyDown' ? '\r' : undefined });
26	}
27	const busy = () => ev(`!!document.querySelector('[aria-label*="Stop" i]')`);
28	const body = () => ev('document.body.innerText');
29	if (mode !== 'read') {
30	  await sleep(3000);
31	  let last = '', still = 0;
32	  const started = Date.now();
33	  while (Date.now() - started < 420000) {
34	    await sleep(4000);
35	    const now = await body();
36	    still = now === last && !(await busy()) ? still + 1 : 0;
37	    last = now;
38	    if (still >= 3) break;
39	  }
40	  console.log('seconds:', Math.round((Date.now() - started) / 1000));
41	}
42	console.log(await body());
43	socket.close();
44	process.exit(0);
